import pytest
from shopcart import Cart, Product, checkout
from shopcart.pricing import DISCOUNT_THRESHOLD, DISCOUNT_RATE

@pytest.fixture
def cart():
    return Cart()

def test_discount_not_applied_for_below_threshold(cart):
    cart.add(Product("P1", "Pen", 20), 3)
    cart.add(Product("TV", "Television", 2000))
    bill = checkout(cart)
    assert bill["discount"] == 0, "Discount should not be applied for orders below Rs 1,000"
    assert bill["subtotal"] == 20 * 3 + 2000, "Subtotal should be Rs 800"
